css='''*{box-sizing:border-box}body{margin:0;background:#081c36;color:#fff;font-family:Arial}.slide{display:none;position:relative;width:1920px;height:1080px;padding:65px 80px;overflow:hidden;background:radial-gradient(ellipse at top right,#174e73,#081c36 70%)}.active{display:block}.tag{color:#ffad72;letter-spacing:2px;font-size:24px;font-weight:bold}h1{font-size:62px;line-height:1.15;margin:25px 0 32px}h2{font-size:36px;margin:0 0 20px}p,li{font-size:29px;line-height:1.5}p{margin:16px 0}.cue{display:table;width:auto}.footer{position:absolute;bottom:30px;left:80px;right:80px;display:flex;justify-content:space-between;color:#bed2e5;font-size:22px}.hero{position:absolute;left:80px;top:370px;width:1140px;border:5px solid #4085a8;border-radius:22px}.cover-side{position:absolute;left:1280px;top:440px;width:520px}.cover-side p{font-size:36px;line-height:1.65}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:26px;margin-top:50px}.card{border-radius:22px;padding:30px;background:#eaf4fc;color:#102848;border:2px solid #91bbd4;min-height:330px}.card:nth-child(3n+2){background:#ecf9f2}.card:nth-child(3n){background:#f4efff}.card h2{color:#123f62}.card .number{display:inline-block;background:#ff6b24;color:white;font-size:28px;padding:13px 20px;border-radius:50%;margin-bottom:20px}.two{display:grid;grid-template-columns:1fr 1fr;gap:44px;margin-top:45px}.two p{font-size:32px;line-height:1.55}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:26px/1.55 Consolas,monospace;margin:16px 0 0;color:white}.code{background:#172d43;border:2px solid #4085a8;border-radius:22px;padding:30px;min-height:490px}.code .label{color:#ffad72;font-size:22px;margin-bottom:22px}.banner{background:#164568;border:1px solid #4e92b6;border-radius:18px;padding:20px 30px;margin-top:30px}.banner p{margin:0}.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;margin-top:42px}.steps .card{min-height:250px}.steps h2{font-size:29px}.steps p{font-size:25px}.rail{position:absolute;bottom:95px;left:80px;right:80px;display:flex;align-items:center;gap:15px}.rail b{flex:1;background:#173b59;color:#c5d9e9;text-align:center;border:1px solid #4085a8;border-radius:12px;padding:17px;font-size:22px}.rail b.on{background:#c55326;color:#fff}.arrow{font-size:30px;color:#ffad72}.diagram{position:relative;margin-top:35px;height:590px}.node{position:absolute;background:#eaf4fc;border:2px solid #91bbd4;border-radius:20px;padding:24px;color:#102848;width:380px;min-height:170px}.node h2{font-size:31px;margin-bottom:14px}.node p{font-size:26px}.node.orange{background:#d35d2b;color:white}.svg{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.seq{width:1760px;height:680px;margin-top:12px}.seq text{font-family:Arial}.seq .head{fill:#eaf4fc;stroke:#91bbd4}.seq .cloud{fill:#c55326}.seq .life{stroke:#7193ae;stroke-dasharray:7 7;stroke-width:2}.seq .msg{stroke:#c7dce9;stroke-width:2.5}.seq .return{stroke:#ffad72;stroke-width:2.5;stroke-dasharray:8 5}.seq .label{fill:white;font-size:24px}.shot{position:absolute;left:80px;top:230px;width:1300px;border:3px solid #4085a8;border-radius:16px}.shot-note{position:absolute;left:1430px;top:255px;width:400px}.shot-note p{font-size:31px}'''
