def cue(id,text):return f'<div class="cue" data-cue="{id}">{text}</div>'
def head(k,title):return f'<div class="tag">{k}</div><h1>{title}</h1>'
def card(id,title,body,num=None):return '<article class="card">'+(f'<span class="number">{num}</span>' if num else '')+cue(id,f'<h2>{title}</h2><p>{body}</p>')+'</article>'
add('Learning Platform Tech Stack and Architecture',head('CLAUDE MANAGED AGENTS · GITHUB MAIN 7717a10','Tech Stack<br>and Architecture')+'<img class="hero" src="portal-cover.png"><div class="cover-side">'+cue('cover-route','<p>Understand the layers.<br>Trace one request.<br>Read the implementation.</p>')+'</div>',[('cover-route','Welcome to the Claude Managed Agents learning platform architecture lesson. We will explore the technologies, understand what runs where, and follow a request from the browser to a managed session and back.')],['package.json','server/index.ts','vite.config.ts'])
add('What you will understand',head('YOUR ROUTE THROUGH THIS LESSON','From the screen to the managed runtime')+'<div class="grid">'+card('index-stack','1 · Technology stack','React and Vite<br>Node, Express and TypeScript<br>Zod and the Anthropic SDK')+card('index-architecture','2 · Architecture','Browser and backend boundaries<br>Typed contracts and lesson modules<br>Local and remote execution')+card('index-flow','3 · Request workflow','A sequence diagram<br>Eight implementation steps<br>Storage, cleanup and tests')+'</div>',[('index-stack','First, identify the technologies used by this repository and the job each one performs.'),('index-architecture','Then separate the browser, host backend, shared contracts, and remote runtime.'),('index-flow','Finally, trace a Lab zero one request through eight steps, with code excerpts, storage boundaries, and verification tools.')])
